def extract_source_lines():
    if not SRC.exists():
        return None
    lines = SRC.read_text(encoding='utf-8').splitlines()
    return len(lines)

def write_data():
    for p in PROJECTS:
        p['tags'] = sorted(set(p['mode'] + p['stage'] + p['disciplines']))
        p['detail_url'] = f"项目详情/{p['id']}.html"
    OUT_JSON.write_text(json.dumps({'source': SOURCE_LABEL, 'source_line_count': extract_source_lines(), 'projects': PROJECTS}, ensure_ascii=False, indent=2), encoding='utf-8')
    fields = ['id','region','country','school','mode','stage','disciplines','xidian_units','score','language','deadline','deadline_month','tuition','scholarship','summary','source','note','tags','detail_url']
    with OUT_CSV.open('w', newline='', encoding='utf-8-sig') as f:
        w=csv.DictWriter(f, fieldnames=fields)
        w.writeheader()
        for p in PROJECTS:
            row=p.copy()
            for k in ['mode','stage','disciplines','xidian_units','tags']:
                row[k]='；'.join(row.get(k,[]))
            w.writerow({k:row.get(k,'') for k in fields})

